import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { join } from "node:path";

const root = new URL("..", import.meta.url).pathname;
const fixture = join(root, "fixtures", "sample.tsv");

// Byte-exact expected stdout (console.log appends a trailing "\n").
const EXPECTED = [
  "total clicks: 9",
  "bad lines: 2",
  "#1 aaa111 2",
  "#2 bbb222 1",
  "#3 ccc333 1",
  "#4 ddd444 1",
  "#5 eee555 1",
  "ref a.com: 1",
  "ref direct: 3",
  "ref news.example.com: 1",
  "ref other: 1",
  "ref other.org: 1",
  "ref sub.example.net: 1",
  "ref z.com: 1",
].join("\n") + "\n";

function run(entry) {
  return execFileSync("node", [entry, fixture], { cwd: root });
}

test("golden: legacy shortstats.js is frozen", () => {
  assert.equal(run(join(root, "shortstats.js")).toString(), EXPECTED);
});

test("golden: typed port matches legacy byte-for-byte", () => {
  const legacy = run(join(root, "shortstats.js"));
  const ported = run(join(root, "dist", "cli.js"));
  assert.ok(legacy.equals(Buffer.from(EXPECTED)), "legacy must equal expected");
  assert.ok(ported.equals(legacy), "dist/cli.js must match legacy byte-for-byte");
});
"})
