result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/stats.test.mjs", "content": "import { test } from "node:test";
import assert from "node:assert/strict";

// Unit tests run against the compiled output (dist/stats.js), so what is
// tested is exactly what the CLI executes.
const { createStats, parseLine, accumulate, renderReport } = await import("../dist/stats.js");

test("parseLine skips empty lines without counting them bad", () => {
  assert.deepEqual(parseLine(""), { kind: "skip" });
});

test("parseLine rejects wrong column counts", () => {
  assert.deepEqual(parseLine("only\ttwo"), { kind: "bad" });
  assert.deepEqual(parseLine("a\tb\tc\td"), { kind: "bad" });
});

test("parseLine rejects codes that are not exactly 6 chars", () => {
  const five = parseLine("abcde\thttps://x.com\t1");
  assert.equal(five.kind, "bad");
  const seven = parseLine("abcdefg\thttps://x.com\t1");
  assert.equal(seven.kind, "bad");
});

test("parseLine accepts a well-formed row", () => {
  assert.deepEqual(parseLine("abc123\thttps://x.com/p\t1700"), {
    kind: "row",
    row: { code: "abc123", referrer: "https://x.com/p", ts: "1700" },
  });
});

test("accumulate buckets referrers: direct, host match, other", () => {
  let stats = createStats();
  for (const ref of ["-", "https://a.com/x", "http://sub.a.com/", "not a url"]) {
    stats = accumulate(stats, parseLine(`abc123\t${ref}\t1`));
  }
  assert.equal(stats.total, 4);
  assert.equal(stats.bad, 0);
  assert.deepEqual(Object.fromEntries(stats.referrers), {
    direct: 1,
    "a.com": 1,
    "sub.a.com": 1,
    other: 1,
  });
});

test("accumulate counts clicks per code", () => {
  let stats = createStats();
  stats = accumulate(stats, parseLine("abc123\t-\t1"));
  stats = accumulate(stats, parseLine("abc123\t-\t2"));
  stats = accumulate(stats, parseLine("xyz789\t-\t3"));
  assert.equal(stats.clicks.get("abc123"), 2);
  assert.equal(stats.clicks.get("xyz789"), 1);
});

test("stats objects are immutable — no shared module state", () => {
  const before = createStats();
  const after = accumulate(before, parseLine("abc123\t-\t1"));
  assert.notEqual(before, after);
  assert.equal(before.total, 0);
  assert.equal(after.total, 1);
  assert.equal(before.clicks.size, 0);
  assert.equal(after.clicks.size, 1);
});

test("renderReport truncates to top 5 and breaks count ties alphabetically", () => {
  let stats = createStats();
  // zzz999 and mmm333 tie at 2; alphabetical order must win inside a tier.
  for (const code of ["zzz999", "mmm333", "zzz999", "mmm333"]) {
    stats = accumulate(stats, parseLine(`${code}\t-\t1`));
  }
  for (const code of ["aaa111", "bbb222", "ccc444", "ddd555", "eee666", "fff777"]) {
    stats = accumulate(stats, parseLine(`${code}\t-\t1`));
  }
  const report = renderReport(stats).split("\n");
  assert.equal(report[0], "total clicks: 10");
  assert.equal(report[1], "bad lines: 0");
  assert.deepEqual(
    report.slice(2, 7),
    ["#1 aaa111 1", "#2 bbb222 1", "#3 ccc444 1", "#4 ddd555 1", "#5 eee666 1"],
  );
});
"})
